"""Build and qualify the existing CYBR spectral shader interface."""
from pathlib import Path
import sys,json,hashlib,struct,tempfile,subprocess,ctypes,numpy as np
from iv_coastal_life import r,Bathymetry,state
from iv_coastal_return import water_return,ABSORPTION,BACKSCATTER_550,BACKSCATTER_EXPONENT,BOTTOM_CONTROLS,IOR
from cybr_light import Scene
from cybr_light.runtime import publish
out=r/'evidence/full-iv-coastal-return';out.mkdir(exist_ok=True);cpp=r/'work/iv_coastal_return_shader.cpp';library=out/'iv_coastal_return_shader.so'
command=['g++','-std=c++17','-O2','-shared','-fPIC',str(cpp),'-o',str(library)];subprocess.run(command,check=True,capture_output=True)
lib=ctypes.CDLL(str(library));fn=lib.cybr_shader;fn.argtypes=[ctypes.c_double]*3+[ctypes.POINTER(ctypes.c_double)]*3;fn.restype=None;parameters=(ctypes.c_double*3)(0,0,0);gradient=(ctypes.c_double*3)();value=ctypes.c_double();rng=np.random.default_rng(201611);h=np.r_[np.zeros(95),np.full(95,.5),np.full(95,1000.),rng.uniform(0,30,5000)];w=np.r_[np.arange(360.,831.,5.),np.arange(360.,831.,5.),np.arange(360.,831.,5.),rng.uniform(360,830,5000)];expected=np.array([water_return([H],[nm])[0][0,0] for H,nm in zip(h,w)]);actual=[]
for H,nm in zip(h,w):fn(float(nm),float(H),0,parameters,ctypes.byref(value),gradient);actual.append(value.value);assert all(x==0 for x in gradient)
actual=np.asarray(actual);error=float(abs(actual-expected).max());assert np.isfinite(actual).all() and actual.min()>=0 and actual.max()<=1 and error<2e-12
bathy=Bathymetry();source=r/'evidence/full-iv-coastal-life/ocean_transport.clm';dtype=np.dtype([('indices','u1',(3,)),('material','<u4'),('object','<u4')]);original_geom=hashlib.sha256();new_geom=hashlib.sha256();depths=[]
with source.open('rb') as f,tempfile.NamedTemporaryFile(prefix='cybr-water-spectral-',suffix='.clm',delete=False) as dst:
 temporary=Path(dst.name);header=f.read(16);magic,total,packets=struct.unpack('<4sQI',header);assert magic==b'CLM1';dst.write(header)
 for _ in range(packets):
  head=f.read(4);nv,nt=struct.unpack('<HH',head);v=np.frombuffer(f.read(nv*44),'<f4').reshape(nv,11).copy();tri=np.frombuffer(f.read(nt*11),dtype).copy();original_geom.update(v[:,:6].tobytes());depth=np.maximum(0,v[:,2].astype(float)-bathy.sample(v[:,:2]));assert depth.max()<30;v[:,6]=depth;v[:,7]=0;v[:,8:11]=1;tri['material']=191;new_geom.update(v[:,:6].tobytes());dst.write(head);dst.write(v.tobytes());dst.write(tri.tobytes());depths.extend(depth.tolist())
 assert not f.read(1)
assert original_geom.hexdigest()==new_geom.hexdigest();publish(temporary,out/'water_return_spectral.clm')
s=Scene();s.materials=191;s.material('plastic',(1,1,1),rough=state['native_roughness_parameter'],ior=IOR);s.emit('shader',191,json.dumps(str(library.resolve())),0,0,0);s.save(out/'materials_spectral.cys')
zero,t=water_return([0],np.arange(360.,831.,5.));assert np.allclose(t['subsurface_rrs_sr-1'][0],t['substrate_spectrum']/np.pi,atol=1e-12)
deep,t=water_return([1000],np.arange(360.,831.,5.));assert np.allclose(deep[0],np.pi*t['deep_rrs_sr-1']/(IOR**2*(1-1.562*t['deep_rrs_sr-1'])),atol=1e-12)
record={'passed':True,'triangles':total,'meshlets':packets,'material_offset':191,'material_count':1,'source_geometry':str(source.relative_to(r)),'positions_normals_unchanged_sha256':new_geom.hexdigest(),'mesh_sha256':hashlib.sha256((out/'water_return_spectral.clm').read_bytes()).hexdigest(),'cpp_source_sha256':hashlib.sha256(cpp.read_bytes()).hexdigest(),'library_sha256':hashlib.sha256(library.read_bytes()).hexdigest(),'compiler':subprocess.check_output(['g++','--version'],text=True).splitlines()[0],'compile_command':command,'native_shader_vs_python_points_checked':len(actual),'maximum_native_shader_absolute_error':error,'checked_effective_reflectance_range':[float(actual.min()),float(actual.max())],'depth_percentiles_m':np.percentile(depths,[0,1,10,50,90,99,100]).tolist(),'zero_depth_bottom_limit_passed':True,'deep_water_limit_passed':True,'uv_contract':'Water U stores nonnegative physical depth in metres. Native barycentric interpolation supplies per-hit depth to the spectral shader; V is unused. Position and smooth normal bytes are preserved. There is no water normal/height texture requiring the former UV chart.','spectral_contract':'Original formula evaluated at each actual sampled wavelength through the existing cybr_shader API. No three-basis colour reduction of the return function. Estimated bottom reflectance retains its original native spectral basis.','surface_interface_contract':'Native plastic shader supplies the established GGX Fresnel reflection and two transmission factors. The return function includes n^-2 radiance divergence and an approximate internal-return denominator; no second surface reflection is baked into the diffuse term.','authored_absorption_table_nm_m-1':ABSORPTION.tolist(),'authored_backscatter_550_m-1':BACKSCATTER_550,'authored_backscatter_power':BACKSCATTER_EXPONENT,'authored_bottom_native_coefficients':BOTTOM_CONTROLS.tolist(),'primary_reference':'https://doi.org/10.1364/AO.37.006329','accessible_reference':'https://misclab.umeoce.maine.edu/ftp/classes/OO2017/readings/Lee_HS_shallow_waters1_AO1998.pdf','source_model':'Lee et al.1998 equations16 and21 for homogeneous-water nadir subsurface return; paper internal-return factor1.562. Explicit authored optical state, measured CoNED depth.','original_adapter':'Below0.5m the empirical model is smoothly bridged to the zero-depth bottom/pi limit. The nadir return is treated as a Lambertian substrate term beneath native Fresnel. No measured angular calibration or generic water-volume equivalence.','limits':'Surface-return approximation, not native volume transport. Empirical nadir coefficients used in an oblique view; the source paper\u2019s Hydrolight error is not claimed. No local water-quality observations, underwater parallax/object visibility, breaking waves, current coupling, biological dynamics or automatic-differentiation optics claim.'}
(out/'SPECTRAL_SHADER_RECEIPT.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record),flush=True)
